import fs from 'node:fs';
import {spawnSync} from 'node:child_process';
const persist=process.env.PHASE35D_PERSIST||'.wrangler/phase35d-clean';
function query(sql){const r=spawnSync(process.execPath,['node_modules/wrangler/bin/wrangler.js','d1','execute','DB','--local','--config','wrangler.35d.local.jsonc','--persist-to',persist,'--command',sql,'--json'],{encoding:'utf8',maxBuffer:20*1024*1024});if(r.status)throw Error(r.stderr||r.stdout);return JSON.parse(r.stdout.slice(r.stdout.indexOf('[')))[0].results;}
const units=query('SELECT id,language,stage,topic_id,title,objective,sequence,status,estimated_minutes FROM lesson_units ORDER BY language,stage,sequence'),prerequisites=query('SELECT lesson_id,prerequisite_lesson_id FROM lesson_prerequisites ORDER BY lesson_id'),items=query('SELECT lesson_id,content_type,content_id,role,sequence,required FROM lesson_items ORDER BY lesson_id,content_type,sequence'),exams=query('SELECT framework_id,target,lesson_id,relevance FROM lesson_exam_recommendations ORDER BY framework_id,target,lesson_id');
const payload={v:'3.5D.1',u:units.map(Object.values),p:prerequisites.map(Object.values),i:items.map(Object.values),e:exams.map(Object.values)};
const json=JSON.stringify(payload).replaceAll("'","''");
const sql=`-- Quota-safe, versioned Phase 3.5D composition document.\nCREATE TABLE lesson_bundles (id TEXT PRIMARY KEY,schema_version TEXT NOT NULL,payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),published_at TEXT NOT NULL);\nINSERT INTO lesson_bundles(id,schema_version,payload_json,published_at) VALUES('phase-35d-v1','3.5D.1','${json}','2026-09-10T00:00:00Z');\n`;
fs.mkdirSync('migrations-35d-bundle',{recursive:true});fs.writeFileSync('migrations-35d-bundle/0001_bundle.sql',sql);fs.writeFileSync('src/lesson-bundle-35d.js',`// Generated from the audited composition layer. Do not hand-edit.\nexport default ${JSON.stringify(payload)};\n`);console.log(`Generated ${Buffer.byteLength(json)} byte bundle: ${units.length} lessons, ${items.length} links.`);
